/**
 * Detects crash/fall impacts with a confirmation window.
 */
public protocol ImpactDetectorProtocol: AnyObject, Sendable {
    
    /**
     * User cancels a candidate ("I'm fine") — no confirmed event will fire.
     */
    func cancel(id: Int64)  -> Bool
    
    /**
     * Fires confirmed events for candidates whose deadline has elapsed without
     * a cancel. Call on a timer.
     */
    func checkConfirmations(nowMs: Int64)  -> [ImpactEvent]
    
    /**
     * User (or app) explicitly confirms a candidate is a real emergency now.
     */
    func confirm(id: Int64, nowMs: Int64)  -> ImpactEvent?
    
    /**
     * Folds a **barometric pressure change** (hPa, peak−trough over the impact
     * window) into the most recent pending crash for the cabin-pressure cue
     * (#173). Call once, right after a `potential_crash`, with the pressure
     * swing measured by the device barometer (`Sensor.TYPE_PRESSURE` on Android,
     * `CMAltimeter` on iOS).
     *
     * A sudden spike (airbag deployment / severe collision) is a strong crash
     * corroborator, so it *raises* the candidate's confidence. Like Δv it never
     * lowers confidence or cancels: most devices have no barometer, so its
     * absence (a flat/zero reading) must leave detection unchanged — the cue is
     * strictly "where available". Returns `true` when a candidate was found and a
     * pressure spike corroborated it.
     */
    func corroborateBarometric(pressureDeltaHpa: Double, nowMs: Int64)  -> Bool
    
    /**
     * Folds a **post-impact speed** sample into the most recent pending crash
     * for Δv corroboration (#181). Call once, ~1–2 s after a `potential_crash`,
     * with the current GPS speed (m/s).
     *
     * A sharp collapse of the pre-impact speed (e.g. 60 → 0 km/h) is one of the
     * strongest single crash discriminators, so it *raises* the candidate's
     * confidence. It deliberately never lowers confidence or cancels: a real
     * crash can kill the GPS feed (no/garbage post-impact sample), and crash
     * detection favours recall behind a user cancel-countdown (#173). Returns
     * `true` when a candidate was found and a collapse corroborated it.
     */
    func corroborateDv(speedAfterMps: Double, nowMs: Int64)  -> Bool
    
    /**
     * Feeds one accel window's peak plus motion context. Returns a
     * `potential_*` event when an impact is detected (and registers it for
     * confirmation), else `None`.
     */
    func onImpactWindow(peakG: Double, speedBeforeMps: Double, gyroPeakDps: Double, wasInFreeFall: Bool, postImpactStill: Bool, isOnFoot: Bool, latitude: Double, longitude: Double, nowMs: Int64, crashProba: Double, crashProbaThreshold: Double)  -> ImpactEvent?
    
    /**
     * Number of candidates awaiting confirmation.
     */
    func pendingCount()  -> UInt32
    
    /**
     * Clears all pending candidates.
     */
    func reset() 
    
}
