// Note that we don't yet support `indirect` for enums.
// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.
/**
 * Confidence level of the associated physical activity.
 */

public enum ActivityConfidence: Equatable, Hashable {
    
    case low
    case medium
    case high





}

#if compiler(>=6)
extension ActivityConfidence: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeActivityConfidence: FfiConverterRustBuffer {
    typealias SwiftType = ActivityConfidence

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ActivityConfidence {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .low
        
        case 2: return .medium
        
        case 3: return .high
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: ActivityConfidence, into buf: inout [UInt8]) {
        switch value {
        
        
        case .low:
            writeInt(&buf, Int32(1))
        
        
        case .medium:
