/**
 * Calculates the great-circle distance between two points on the Earth's surface using the Haversine formula.
 * Returns the distance in meters.
 */
public func haversine(lat1: Double, lon1: Double, lat2: Double, lon2: Double) -> Double  {
    return try!  FfiConverterDouble.lift(try! rustCall() {
    uniffi_tracelet_core_fn_func_haversine(
        FfiConverterDouble.lower(lat1),
        FfiConverterDouble.lower(lon1),
        FfiConverterDouble.lower(lat2),
        FfiConverterDouble.lower(lon2),$0
    )
})
}
/**
 * Uses the ray-casting algorithm to determine if a point is strictly inside a polygon.
 */
public func isPointInPolygon(lat: Double, lng: Double, vertices: [Coordinate]) -> Bool  {
    return try!  FfiConverterBool.lift(try! rustCall() {
    uniffi_tracelet_core_fn_func_is_point_in_polygon(
        FfiConverterDouble.lower(lat),
        FfiConverterDouble.lower(lng),
        FfiConverterSequenceTypeCoordinate.lower(vertices),$0
    )
})
}
/**
 * Computes [`AccelWindow`] features from a batch of gravity-subtracted
 * magnitudes (g) spanning `duration_ms`.
 */
public func computeAccelWindow(magnitudesG: [Double], durationMs: Int64) -> AccelWindow  {
    return try!  FfiConverterTypeAccelWindow_lift(try! rustCall() {
    uniffi_tracelet_core_fn_func_compute_accel_window(
        FfiConverterSequenceDouble.lower(magnitudesG),
        FfiConverterInt64.lower(durationMs),$0
    )
})
}
/**
 * Location-filter thresholds appropriate to a detected [`TransportMode`].
 *
 * Returns `None` for [`TransportMode::Unknown`], meaning "leave the host's own
 * configuration alone" — an unclassified stretch is not evidence for any
 * particular tuning, so the caller should keep whatever it already had.
 *
 * The values are chosen for distance fidelity, which is the opposite tension
 * from [`crate::algorithms::location_processor::AdaptiveSamplingEngine`]: that
 * engine widens the distance filter for slow movers to spare the radio, while
 * this table *tightens* it, because walking is exactly where GPS noise is
 * largest relative to real displacement and where an over-wide odometer
 * accuracy gate inflates distance most.
 *
 * `max_implied_speed` sits roughly 2x above each mode's realistic ceiling, so
 * it rejects teleport spikes without clipping genuine bursts.
 */
public func tuningForTransportMode(mode: TransportMode) -> LocationTuning?  {
    return try!  FfiConverterOptionTypeLocationTuning.lift(try! rustCall() {
    uniffi_tracelet_core_fn_func_tuning_for_transport_mode(
        FfiConverterTypeTransportMode_lower(mode),$0
    )
})
}
/**
 * Builds a deterministic canonical string from a location record and its preceding chain hash.
 */
public func buildCanonicalString(previousHash: String, chainIndex: Int32, loc: LocationRecord) -> String  {
    return try!  FfiConverterString.lift(try! rustCall() {
    uniffi_tracelet_core_fn_func_build_canonical_string(
        FfiConverterString.lower(previousHash),
        FfiConverterInt32.lower(chainIndex),
        FfiConverterTypeLocationRecord_lower(loc),$0
    )
})
}
/**
 * Computes the genesis hash for a new device, seeding the audit chain.
 */
public func computeGenesisHash(deviceId: String) -> String  {
    return try!  FfiConverterString.lift(try! rustCall() {
    uniffi_tracelet_core_fn_func_compute_genesis_hash(
        FfiConverterString.lower(deviceId),$0
    )
})
}
/**
